CREATE TABLE IF NOT EXISTS textkeep.users(uid text PRIMARY KEY, email_digest text NOT NULL UNIQUE, consent_version text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), disabled boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS textkeep.devices(id uuid PRIMARY KEY, owner text NOT NULL REFERENCES textkeep.users(uid), name text NOT NULL, token_hash text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, last_sync timestamptz);
CREATE TABLE IF NOT EXISTS textkeep.messages(id uuid PRIMARY KEY, owner text NOT NULL REFERENCES textkeep.users(uid), device uuid NOT NULL REFERENCES textkeep.devices(id), epoch uuid NOT NULL, provider_id text NOT NULL, revision bigint NOT NULL, payload text NOT NULL, sender_digest text NOT NULL, source_date bigint NOT NULL, date_sent bigint NOT NULL, box smallint NOT NULL CHECK(box BETWEEN 1 AND 6), is_read boolean NOT NULL, seen boolean NOT NULL, thread_id text NOT NULL, subscription_id integer NOT NULL, sensitive boolean NOT NULL, ingested_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner,device,epoch,provider_id));
CREATE INDEX IF NOT EXISTS messages_owner_date ON textkeep.messages(owner,source_date DESC,id DESC);
CREATE INDEX IF NOT EXISTS messages_sender ON textkeep.messages(owner,sender_digest,source_date DESC,id DESC);
CREATE INDEX IF NOT EXISTS messages_device ON textkeep.messages(owner,device,source_date DESC,id DESC);
CREATE TABLE IF NOT EXISTS textkeep.ingestion_batches(owner text NOT NULL, device uuid NOT NULL, batch_id uuid NOT NULL, request_digest text NOT NULL, acknowledgements jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(owner,device,batch_id));
CREATE TABLE IF NOT EXISTS textkeep.message_suppressions(owner text NOT NULL, device uuid NOT NULL, epoch uuid NOT NULL, provider_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(owner,device,epoch,provider_id));
CREATE TABLE IF NOT EXISTS textkeep.personal_access_tokens(id uuid PRIMARY KEY, owner text NOT NULL REFERENCES textkeep.users(uid), name text NOT NULL, hash text NOT NULL UNIQUE, sensitive boolean NOT NULL DEFAULT false, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS textkeep.oauth_objects(model text NOT NULL,id text NOT NULL,payload text NOT NULL,grant_id text,user_code text,uid text,expires_at timestamptz,consumed_at timestamptz,PRIMARY KEY(model,id));
CREATE INDEX IF NOT EXISTS oauth_grants ON textkeep.oauth_objects(grant_id);
CREATE TABLE IF NOT EXISTS textkeep.audit_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,owner text,client text,action text NOT NULL,message_ids jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS textkeep.schema_migrations(version text PRIMARY KEY,applied_at timestamptz NOT NULL DEFAULT now());
